[{"order":1,"type":"heading","text":"NavMesh, NavMeshAgents, and Off-Mesh Links in Unity"},{"order":2,"type":"paragraph","text":"Pathfinding is a core requirement for most 3D and 2D games. Unity provides a robust, built-in navigation system powered by NavMesh (Navigation Mesh). This tutorial covers the fundamentals of baking a NavMesh, moving characters using NavMeshAgents, and bridging disconnected areas with Off-Mesh Links."},{"order":3,"type":"heading","text":"1. Understanding NavMesh Fundamentals"},{"order":4,"type":"paragraph","text":"A NavMesh approximates the walkable surfaces of your game environment as a convex polygon mesh. Instead of calculating collisions against every complex geometry, agents calculate paths across this simplified topological representation."},{"order":5,"type":"bullet_point","text":"Navigation Surface: Represents areas where characters can walk."},{"order":6,"type":"bullet_point","text":"Baking: The process of analyzing static level geometry and generating the NavMesh data."},{"order":7,"type":"heading","text":"2. Setting Up and Baking a NavMesh"},{"order":8,"type":"paragraph","text":"To bake a NavMesh in Unity, ensure your floor and static obstacles are marked as "Navigation Static". Then, open the Navigation window via Window > AI > Navigation, select the Bake tab, and click Bake."},{"order":9,"type":"heading","text":"3. Implementing NavMeshAgent"},{"order":10,"type":"paragraph","text":"The NavMeshAgent component sits on your game characters and handles path calculation, steering, obstacle avoidance, and movement. Below is a C# script to make an agent move toward a clicked destination on the NavMesh using raycasting."},{"order":11,"type":"code","text":"using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(NavMeshAgent))]
public class PlayerController : MonoBehaviour
{
    private NavMeshAgent agent;
    private Camera mainCamera;

    void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        mainCamera = Camera.main;
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            Ray ray = mainCamera.ScreenPointToRay(Input.mousePosition);
            if (Physics.Raycast(ray, out RaycastHit hit))
            {
                agent.SetDestination(hit.point);
            }
        }
    }
}"},{"order":12,"type":"heading","text":"4. Using Off-Mesh Links"},{"order":13,"type":"paragraph","text":"Sometimes your level contains gaps that a NavMesh cannot bridge automatically, such as ledges, gaps between platforms, or jump pads. Off-Mesh Links tell the pathfinder how an agent can traverse these disconnected spaces."},{"order":14,"type":"bullet_point","text":"Manual Links: Create an empty GameObject with an Off-Mesh Link component, specifying a start and end transform."},{"order":15,"type":"bullet_point","text":"Automatic Links: Configured in the Navigation window under the Bake settings (e.g., setting Drop Height and Jump Distance)."},{"order":16,"type":"heading","text":"5. Checking Off-Mesh Link Traversal"},{"order":17,"type":"paragraph","text":"By default, agents teleport across Off-Mesh Links instantly. You can override this behavior in your code to execute custom animations, such as a jumping or climbing sequence."},{"order":18,"type":"code","text":"using UnityEngine;
using UnityEngine.AI;

public class AgentLinkMover : MonoBehaviour
{
    IEnumerator Start()
    {
        NavMeshAgent agent = GetComponent<NavMeshAgent>();
        agent.autoTraverseOffMeshLink = false;

        while (true)
        {
            if (agent.isOnOffMeshLink)
            {
                OffMeshLinkData data = agent.currentOffMeshLinkData;
                Vector3 startPos = data.startPos;
                Vector3 endPos = data.endPos;
                float duration = 0.5f;
                float normalizedTime = 0.0f;

                while (normalizedTime < 1.0f)
                {
                    normalizedTime += Time.deltaTime / duration;
                    transform.position = Vector3.Lerp(startPos, endPos, normalizedTime);
                    yield return null;
                }

                agent.CompleteOffMeshLink();
            }
            yield return null;
        }
    }
}"},{"order":19,"type":"heading","text":"Conclusion"},{"order":20,"type":"paragraph","text":"You have successfully learned how to bake a NavMesh, control movement via NavMeshAgents, and link separate navigation areas using Off-Mesh Links. Combine these components with animations and state machines to create intelligent, responsive AI characters in Unity."}]
